"""Seal existing offline analysis and source-index; no raw replay/physics/Git."""
from pathlib import Path
import datetime,hashlib,json,re
R=Path(__file__).resolve().parent

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def new(p,obj):assert not p.exists();p.write_text(json.dumps(obj,ensure_ascii=False,indent=2,allow_nan=False)+'\n',encoding='utf-8')
def meta(p):return {'path':str(p),'relative':p.relative_to(R).as_posix(),'bytes':p.stat().st_size,'SHA':sha(p)}
def main():
    assert not (R/'INDEX.json').exists();data=json.loads((R/'analysis_attempts/001/output/RESULT.json').read_text(encoding='utf-8'));v=json.loads((R/'analysis_attempts/001/VALIDATION.json').read_text(encoding='utf-8'))
    for e in v['source']:assert sha(Path(e['path']))==e['SHA']
    for p,h in v['protected_unchanged'].items():assert sha(Path(p))==h
    table=[]
    for c in data['cases']:
        s=c['sparse_snapshots'];p=s['pre_first_nonwheel'];n=s['first_nonwheel_bin'];f=s['terminal'];table.append({'case':c['case'],'target_root_level_z_m':c['nominal_target']['root_level_height_m'],'target_leg_length_m':c['nominal_target']['leg_length2_m'][0],'t_nonwheel_bin_s':n['bin_s'],'rootZ_post_m':n['root_xyz_post_m'][2],'pitch_post_deg':n['pitch_roll_post_deg'][0],'body_drop_m':n['encoder_body_drop_m'],'shape_drop_loss_m':n['shape_vertical_drop_loss_m'],'posture_projection_loss_m':n['posture_projection_vertical_loss_m'],'nominal_target_drop_m':n['nominal_target_body_drop_m'],'max_angle_tracking_error_rad':n['max_abs_encoder_target_error_rad'],'sparse_firstbin_rigidbox_overlap_candidates':{b['name']:[h['terrain_box'] for h in b['SAT_overlap_candidates_NOT_observed_contact']] for b in n['body_box_geometry']},'terminal_time_s':f['bin_s'][1],'terminal_rootZ_m':f['root_xyz_post_m'][2],'terminal_pitch_deg':f['pitch_roll_post_deg'][0],'progress_m':c['progress_m'],'complete':c['completed'],'rough_pass':c['rough_pass'],'health_flags':c['original_health_stop_flags']})
    new(R/'CASE_CAUSAL_TABLE.json',{'cases':table,'units':'SI; angle display deg','geometry':'sparse analytic8rigid rootbody boxes; not279mesh or contactforces','truth_symmetric_mean_only':'gtstate2=meanhip,3=meancrank-minus-meanhip; actual perleg truthangles not persisted here','two_kHz_event_identity_or_peak_not_reconstructed':True})
    new(R/'STRATEGY_HYPOTHESES.json',{'status':'TESTABLE_NEW_TRAIN_HYPOTHESES_NOT_RUN_NOT_ACCEPTANCE','observed_confounder':'Increasing height also resynthesized DARE gain; not a pure geometry-only intervention','hypotheses':[{'id':'H_pitch_projection','claim':'Fixed leg length targets do not maintain worldvertical clearance once root pitches35–43deg. Preserve pitch/foreaft support and wheel torque-speed reserve before barrier loading, not simply moredelta.','minimal_counterfactual':'Same6cm material/geoms/collisions/model/gainbank and seed; compare baselinefixedlegs with explicitly timed/IMU-pitch-and-wheel-headroom controlled hip/crank foreaft reference trajectory. Keep root unassisted and truth grading separate.','counterexample_to_guard':'Blanket zero-pitch or arbitrary slowing may remove needed climbinglean; evaluate actual progress, wheel/bar transition and nonwheel/health order, not controllercompletion.'},{'id':'H_odom_unload','claim':'High wheel mean rate near nominal no-load with low aligned driving torque is consistent with DC speed limit/common-slip, not proof controller chose weak effort.','minimal_counterfactual':'Bound forward reference integrator/pitch buildup when raw wheel demand reaches signed DCheadroom and bodygyro/encoder motion inconsistent; no worldposition or truth feedback.','boundary':'Mean wheel rate and endstep torque differ in time; need new synchronized telemetry for exact2kclipping fraction, cannot infer it from old trace.'},{'id':'H_static_clearance','claim':'Upright nominal chassis rigidboxes have>107mm margin above6cm even atdelta0, so static inevitable chassis blockage is not established.','counterexample':'Guide/links/tilted swept envelope and tinywheel-radius step geometry remain; do not claim fullbodyclearance or simply delete collisions.'}],'preserve_scope':'No height reduction/contact deletion/fake weaker-model pass. ExistingR30 guidepriority variant remains separate parameter-selection model.'})
    new(R/'EVIDENCE_BOUNDARIES.json',{'newphysics':0,'newSDKcalls':0,'newGit_GPU_agents_realIO':False,'authorized_training_cases': [x['case'] for x in table],'H1_H2_H4_used':False,'root_truth':'offline grading only, never controller input','sampling':'q/qd andestimate at acquisition/precontrol; rootpose_after=t+.01; collision/sitecache_after-.0005; nonwheel first known only20step bin','identity':'R22does not persist namedgeom2k contactidentity. SparseSAT is reconstructedcandidate not actualforce. R30namedcore/bar011 is independent-case proof, not R22identity.','physical_model':'SignedDC clip; high positive wheel speed reduces same-sign motoring torque but may retain opposite braking torque. Mean-speed diagnostic cannot exactly reconstruct endstep envelope.','health':'Four higherposture cases stop by upright_cos<.45, not closure/mimic>.01/nonfinite. Analysisangle thresholds are markers only.','reader_event':'READER_EVENTS.json','metadata_wording_erratum':'analysis RESULT geometrylimits says chassis4box; algorithm actually extracts8rootbodyboxgeoms inclsidearmor/motorbay. All8 are in outputs; no force reconstruction.'})
    lines=[]
    for c in table:lines.append(f"|{c['case']}|{c['target_root_level_z_m']:.6f}|{c['t_nonwheel_bin_s'][0]:.3f}–{c['t_nonwheel_bin_s'][1]:.3f}|{c['rootZ_post_m']:.6f}|{c['pitch_post_deg']:.3f}|{1000*c['shape_drop_loss_m']:.3f}|{1000*c['posture_projection_loss_m']:.3f}|{c['progress_m']:.6f}|{'complete' if c['complete'] else 'health'}|")
    md='''# Rough Posture Causal v1 — R22existing TRAIN, no new physics\n\n**主要观察：delta0/.2/.4确实抬高nominal几何，但首非轮bin前已出现显著pitch。此时BODY腿竖直drop并未缩短，而旋转到world的竖直投影损失约7–12cm，压过增加高度收益。更高固定腿姿四案后来因upright<.45结束；不是闭链先坏。**\n\n## 精简因果表\n\nshape loss定义target BODYdrop−observed encoderFK BODYdrop，负值代表观察姿态在BODY反而更长。projection loss定义BODYdrop−post-truth旋转后的world竖直drop。sensorq与postroot姿态相差一个控制interval，数值为近似分解，不是瞬时完整truth姿态。\n\n|case|target level rootZ m|first非轮bin s|rootZ m|pitch deg|shape loss mm|projection loss mm|progress m|stop|\n|---|---:|---:|---:|---:|---:|---:|---:|---|\n'''+ '\n'.join(lines)+'''\n\n[CASE表](<CASE_CAUSAL_TABLE.json>)与[完整analysis](<analysis_attempts/001/output/RESULT.json>)给角度、腿几何、wheel速度/τ、health及每个关键时刻8root-body box包络。\n\n## 几何与事件顺序\n\nnominal delta0/.2/.4：leg planar长度.273242/.304462/.333924m，upright root高.334876/.366405/.396124m。所有8个rootbodyrigidbox中最低belly对6cm顶面净距107.876/139.405/169.124mm，故不能声称uprightnominal也必然chassis碰6cm。此几何并未保证guide/link/tire或动态转移可通过。\n\n首nonwheel20stepbin之前：pitch已达35–43deg；wheel endstep曾达5.7759Nm峰限；腿绝对角误差曾超过.05rad。但“角误差”不等于“腿回缩”，数据反而显示BODYdrop增大。控制器固定4输出角，没直接控制worldrootZ。\n\n较高四案terminal upright_cos=.423–.448<.45，closure约3e−7m/mimic约1e−6rad，未触原.01门槛。低姿两案complete但rough未过；停住/尾速小/完成不能变成通过。\n\nwheel mean约53.8–53.9rad/s与endstepτ约.77–.79Nm，对55.3557nominal no-load的同向DC motoring limit下降一致。原clip是SIGNED，逆向制动力矩不等于同向motor能力；这里mean速度与最后stepτ不同时间，2k峰值/饱和占比未保存，不能精确重建。\n\n## R30证据与身份边界\n\n另四个R30existing小报告保留在analysis里：6cm原模型tire/bar0112.564s→chassis_core/bar0112.680s、force12780.99N，随后guideground。它说明实际动态bodyblocker机制，但不能倒填成R22每案的第一身份。R22只有aggregate非轮pair/point ticks每20step，不是去重physicsstep。\n\n稀疏解析SAT只表示指定postrootpose下某rootbox与已存barbox几何候选；没重跑collision/force、没279mesh逐tick、没2k事件。postframe无overlap不证明bin内无接触；全部命名未知照留。真实fullassetCAD/所有11family或PhysX equivalence仍不在该tiny_step数据中。\n\n## 下一最小可检验动作（未执行）\n\n[策略假设](<STRATEGY_HYPOTHESES.json>)建议先在同6cm/model/contact/gainbank下比较：在bar加载/轮motorheadroom耗尽前，用真实IMU/encoder允许的pitch/foreaft参考轨迹保住world投影与动态reserve；不是继续只抬delta，也不是笼统更慢或删碰撞。固定target完全竖直/零pitch也可能消掉必要爬阶lean，必须同时看progress/轮bar转移/非轮与health顺序。高度改变同时重算DAREgain是confounder，不冒纯几何因果试验。\n\n所有GT只用于离线grading；不输出在线truth控制、rootassist或新物理。旧trace仅为本次授权因果分析流读，producerSHA沿用，不为归档重hash大raw。H1/H2/H4未读作选择。[初步表](<INTERIM.json>)此前已交父，最终证据更正必须以本表为准。\n\n## Source/验证\n\n[scope](<SCOPE.md>)、[执行源码](<causal_analysis.py>)、[执行前sourceSHA/保护旧源](<analysis_attempts/001/VALIDATION.json>)、[reader事件](<READER_EVENTS.json>)、[边界](<EVIDENCE_BOUNDARIES.json>)、[INDEX](<INDEX.json>)。0physics/SDK/Git/GPU/newagent/真实IO，全部PH4pending。RAW2K任务只在此rough交付后另新目录做。\n'''
    (R/'README.md').write_text(md,encoding='utf-8');new(R/'SOURCE_RESULT_INDEX.json',{'analysis_source':meta(R/'causal_analysis.py'),'result':meta(R/'analysis_attempts/001/output/RESULT.json'),'source_dependencies':data['sources'],'public_model_SHA':data['public_XML_SHA'],'original_raw_trace_only_producerSHA':[{'case':x['case'],'artifact':x['producer_trace']} for x in data['cases']],'newrawhash':False,'protected_source_SHA':v['protected_unchanged']})
    files=sorted(p for p in R.rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.name!='INDEX.json');new(R/'INDEX.json',{'name':'ROUGH_POSTURE_CAUSAL_V1','status':'SEALED_EXISTING_R22_TRAIN_CAUSAL_DIAGNOSTIC_NOT_NEW_ACTION_QUALIFICATION','README':meta(R/'README.md'),'source_result_index':meta(R/'SOURCE_RESULT_INDEX.json'),'case_table':meta(R/'CASE_CAUSAL_TABLE.json'),'physics_SDK_Git_GPU_newagents_realIO':False,'truth_offline_only':True,'H1_H2_H4_used':False,'PH4pending':True,'sealed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'files':[meta(p) for p in files]})
    for p in R.glob('*.md'):
        for link in re.findall(r'\]\(<([^>]+)>\)',p.read_text(encoding='utf-8')):assert (p.parent/link.split('#')[0]).exists()
    print(json.dumps({'INDEX':meta(R/'INDEX.json'),'README':meta(R/'README.md'),'case_table':table,'physics_steps':0},ensure_ascii=False,indent=2))
if __name__=='__main__':main()
